"""Tool to get list of sensor names from VST."""

import json
import logging

from nat.builder.builder import Builder
from nat.builder.framework_enum import LLMFrameworkEnum
from nat.builder.function_info import FunctionInfo
from nat.cli.register_workflow import register_function
from nat.data_models.component_ref import FunctionRef
from nat.data_models.function import FunctionBaseConfig
from pydantic import BaseModel
from pydantic import Field

logger = logging.getLogger(__name__)


class GetSensorNamesConfig(FunctionBaseConfig, name="get_sensor_names"):
    """Configuration for the get sensor names tool."""

    vst_sensor_list_tool: FunctionRef = Field(
        "vst_sensor_list",
        description="The name of the VST sensor list tool to call",
    )


class GetSensorNamesInput(BaseModel):
    """Input for the get sensor names tool (no parameters needed)."""

    pass


class GetSensorNamesOutput(BaseModel):
    """Output for the get sensor names tool."""

    sensor_names: list[str] = Field(
        ...,
        description="List of available sensor names",
    )


@register_function(config_type=GetSensorNamesConfig, framework_wrappers=[LLMFrameworkEnum.LANGCHAIN])
async def get_sensor_names(config: GetSensorNamesConfig, builder: Builder):
    """
    Get a list of available sensor names from VST.

    This tool queries the VST service and returns a simple list of sensor names
    that can be used to query incidents, count objects, or generate reports.
    """

    sensor_list_tool = await builder.get_tool(config.vst_sensor_list_tool, wrapper_type=LLMFrameworkEnum.LANGCHAIN)

    async def _get_sensor_names(input_data: GetSensorNamesInput) -> GetSensorNamesOutput:  # noqa: ARG001
        """Get list of sensor names from VST (input parameter unused but required for API)."""
        try:
            logger.info("Fetching sensor list from VST")
            sensors_str = await sensor_list_tool.ainvoke(input={})

            # Parse the sensor list response
            text = sensors_str.strip()
            if text and text[0] == text[-1] and text[0] in ('"', "'"):
                text = text[1:-1]

            sensor_names = []
            sensors_data = json.loads(text)

            # VST returns dictionary where keys are sensor IDs and values are sensor objects
            if isinstance(sensors_data, dict):
                for sensor_info in sensors_data.values():
                    if isinstance(sensor_info, dict) and "name" in sensor_info:
                        sensor_names.append(sensor_info["name"])

            logger.info(f"Found {len(sensor_names)} sensors: {sensor_names}")
            return GetSensorNamesOutput(sensor_names=sensor_names)

        except Exception as e:
            logger.error(f"Error fetching sensor names: {e}")
            raise

    yield FunctionInfo.create(
        single_fn=_get_sensor_names,
        description=_get_sensor_names.__doc__,
        input_schema=GetSensorNamesInput,
        single_output_schema=GetSensorNamesOutput,
    )
